// Generated by `yarn release:cem`, which `yarn storybook:start` runs first
import manifest from '../../custom-elements.json';

const SEPARATOR = /^ *\|? *:?-+:? *\|[-| :]*$/u;

/**
 * Adds missing outer pipes to Markdown table rows. Most JSDoc tables have none, and
 * the Markdown parser of Storybook docs only detects a table that starts with `|`.
 */
function addTablePipes(markdown: string): string {
  const lines = markdown.split('\n');
  lines.forEach((line, i) => {
    if (i === 0 || !SEPARATOR.test(line) || !lines[i - 1].includes('|')) {
      return;
    }
    for (let row = i - 1; row < lines.length && lines[row].includes('|'); row++) {
      // Single-column tables already have a trailing pipe, adding another one creates an empty column
      let text = lines[row].trim();
      if (!text.startsWith('|')) {
        text = `| ${text}`;
      }
      if (!text.endsWith('|')) {
        text = `${text} |`;
      }
      lines[row] = text;
    }
  });
  return lines.join('\n');
}

function fixDescriptions(value: unknown): void {
  if (Array.isArray(value)) {
    value.forEach(fixDescriptions);
  } else if (value && typeof value === 'object') {
    const object = value as Record<string, unknown>;
    if (typeof object.description === 'string') {
      object.description = addTablePipes(object.description);
    }
    Object.values(object).forEach(fixDescriptions);
  }
}

fixDescriptions(manifest);

export default manifest;
